                frame.writeByte(b1);
            }
        }
        return frame;
    }

    return null;
}

fixed_code:
@Override
protected Object decode(
        ChannelHandlerContext ctx, Channel channel, ByteBuf buf) throws Exception {

    int brackets = 0;
    int endIndex = -1;
    for (int i = buf.readerIndex(); i < buf.writerIndex(); i++) {
        byte b = buf.getByte(i);
        switch (b) {
            case '[':
                brackets += 1;
                break;
            case ']':
                brackets -= 1;
                break;
            default:
                break;
        }
        if (brackets == 0 && i > buf.readerIndex()) {
            endIndex = i + 1;
            break;
        }
    }

    if (endIndex > 0) {
        ByteBuf frame = Unpooled.buffer();
        while (buf.readerIndex() < endIndex) {
            byte b1 = buf.readByte();
            if (b1 == '}') {
                byte b2 = buf.readByte();
                switch (b2) {
                    case 0x01:
                        frame.writeByte('}');
                        break;
                    case 0x02:
                        frame.writeByte('[');
                        break;
                    case 0x03:
                        frame.writeByte(']');
                        break;
                    case 0x04:
                        frame.writeByte(',');
                        break;
                    case 0x05:
                        frame.writeByte('*');
                        break;
                    default:
                        throw new IllegalArgumentException(String.format(
                                "unexpected byte at %d: 0x%02x", buf.readerIndex() - 1, b2));
                }
            } else {
                frame.writeByte(b1);
            }
        }
        return frame;
    }

    return null;
}

